riskyFunctions.matchesContentFilters:
function matchesContentFilters(post){
  const item=state.items[post.id];
  if(currentLineFilter&&item.lineId!==currentLineFilter)return false;
  if(currentBase&&post.base!==currentBase)return false;
  return item.stage===currentView;
}

riskyFunctions.sortStage:
function sortStage(stage){
  const list=allPosts().filter(post=>state.items[post.id].stage===stage);
  if(stage==="queue")return list.sort((a,b)=>timestamp(state.items[a.id].stageChangedAt)-timestamp(state.items[b.id].stageChangedAt));
  if(stage==="editing")return list.sort((a,b)=>timestamp(state.items[b.id].updatedAt)-timestamp(state.items[a.id].updatedAt));
  if(stage==="scheduled")return list.sort((a,b)=>{
    const ad=state.items[a.id].date||"0000-00-00";
    const bd=state.items[b.id].date||"0000-00-00";
    if(!state.items[a.id].date&&state.items[b.id].date)return-1;
    if(state.items[a.id].date&&!state.items[b.id].date)return 1;
    return ad.localeCompare(bd);
  });
  if(stage==="published")return list.sort((a,b)=>(state.items[b.id].date||"").localeCompare(state.items[a.id].date||""));
  return list.sort((a,b)=>a.number-b.number);
}

riskyFunctions.subtitleFor:
function subtitleFor(post){
  const item=state.items[post.id];
  const parts=[post.base];
  if(item.lineId)parts.push(lineName(item.lineId));
  if(item.formats)parts.push(item.formats);
  return parts.join(" · ");
}

