riskyFunctions.workflowMeta:
function workflowMeta(post){
  const item=state.items[post.id];
  if(item.stage==="queue")return`Na fila desde ${formatDateTime(item.stageChangedAt)}`;
  if(item.stage==="editing")return`Atualizado em ${formatDateTime(item.updatedAt)}`;
  if(item.stage==="scheduled")return item.date?`Publicação: ${formatDate(item.date)}`:'<span class="warning">Adicionar data</span>';
  return"";
}

