riskyFunctions.mainCountInWeek:
function mainCountInWeek(date){
  const key=weekKey(date);
  const postCount=allPosts().filter(post=>{
    const item=state.items[post.id];
    return item.date&&weekKey(item.date)===key&&item.behavior!=="parallel";
  }).length;
  const entryCount=state.calendarEntries.filter(entry=>{
    return entry.date&&weekKey(entry.date)===key&&entry.behavior!=="parallel"&&entry.status!=="cancelado";
  }).length;
  return postCount+entryCount;
}

riskyFunctions.fullCalendarEvents:
function fullCalendarEvents(){
  const postEvents=allPosts().flatMap(post=>{
    const item=state.items[post.id];

    if(post.source==="holiday"){
      const dates=(Array.isArray(item.holidayStoryDates)
        ?item.holidayStoryDates
        :[item.date]
      ).filter(Boolean);

      return dates.map((date,index)=>({
        id:`post:${post.id}:story-${index+1}`,
        title:`Story ${index+1}/${dates.length} · ${post.title.replace(/^Stories · /,"")}`,
        start:date,
        allDay:true,
        editable:true,
        backgroundColor:"#ffffff",
        borderColor:"#0A3426",
        textColor:"#0A3426",
        classNames:[
          "adapta-parallel-event",
          "adapta-holiday-story-event",
          item.stage==="published"?"adapta-published-event":""
        ].filter(Boolean),
        extendedProps:{
          sourceType:"post",
          postId:post.id,
          stage:item.stage,
          lineId:item.lineId||"",
          behavior:"parallel",
          occurrenceIndex:index
        }
      }));
    }

    if(!item.date)return[];

    const postIsPublished=item.stage==="published";
    const postIsParallel=item.behavior==="parallel";

    return[{
      id:`post:${post.id}`,
      title:post.title,
      start:item.date,
      allDay:true,
      editable:true,
      backgroundColor:postIsParallel?"#ffffff":postIsPublished?"#17231d":"#0A3426",
      borderColor:postIsParallel?"#0A3426":postIsPublished?"#17231d":"#0A3426",
      textColor:postIsParallel?"#0A3426":"#ffffff",
      classNames:[
        item.behavior!=="parallel"?"adapta-post-event":"",
        item.behavior==="parallel"?"adapta-parallel-event":"",
        item.stage==="published"?"adapta-published-event":""
      ].filter(Boolean),
      extendedProps:{
        sourceType:"post",
        postId:post.id,
        stage:item.stage,
        lineId:item.lineId||"",
        behavior:item.behavior||"main"
      }
    }];
  });

  const entryEvents=state.calendarEntries.filter(entry=>entry.date).map(entry=>{
    const timed=!!entry.time;
    const entryIsHoliday=Boolean(entry.holiday);
    const entryIsSpecial=entry.origin==="avulso";
    const entryIsParallel=entry.behavior==="parallel";

    return{
      id:`entry:${entry.id}`,
      title:entry.title,
      start:timed?`${entry.date}T${entry.time}:00`:entry.date,
      allDay:!timed,
      editable:true,
      backgroundColor:entryIsParallel?"#ffffff":entryIsHoliday?"#a62f2f":entryIsSpecial?"#17231d":"#0A3426",
      borderColor:entryIsParallel?"#0A3426":entryIsHoliday?"#a62f2f":entryIsSpecial?"#17231d":"#0A3426",
      textColor:entryIsParallel?"#0A3426":"#ffffff",
      classNames:[
        "adapta-line-slot-event",
        entry.behavior==="parallel"?"adapta-parallel-event":"",
        entry.holiday?"adapta-holiday-event":"",
        entry.origin==="avulso"?"adapta-special-event":"",
        entry.posted?"adapta-slot-posted":""
      ].filter(Boolean),
      extendedProps:{
        sourceType:"entry",
        entryId:entry.id,
        lineId:entry.lineId||"",
        behavior:entry.behavior||"main",
        status:entry.status||"provisório",
        posted:!!entry.posted
      }
    };
  });

  return[...postEvents,...entryEvents];
}

riskyFunctions.unscheduledCalendarItems:
function unscheduledCalendarItems(){
  const stageOrder={editing:0,queue:1,scheduled:2,ideas:3};

  const entryItems=state.calendarEntries
    .filter(entry=>!entry.date&&entry.status!=="cancelado")
    .map(entry=>({
      sourceType:"entry",
      sourceId:entry.id,
      title:entry.title,
      lineId:entry.lineId||"",
      meta:entry.origin==="linha"?"Slot de linha editorial":"Planejamento",
      sort:entry.origin==="linha"?0:1,
      targetMonth:entry.targetMonth
    }));

  const postItems=allPosts()
    .filter(post=>{
      const item=state.items?.[post.id];
      return item&&!item.date&&item.stage!=="published";
    })
    .map(post=>{
      const item=state.items[post.id];
      return{
        sourceType:"post",
        sourceId:post.id,
        title:post.title,
        lineId:item.lineId||"",
        meta:STAGE_LABELS[item.stage],
        sort:stageOrder[item.stage]??4,
        targetMonth:null
      };
    });

  return[...entryItems,...postItems].sort((a,b)=>{
    if(a.sourceType!==b.sourceType){
      return a.sourceType==="entry"?-1:1;
    }
    if(
      a.sourceType==="entry"
      &&a.targetMonth!==null
      &&b.targetMonth!==null
      &&a.targetMonth!==b.targetMonth
    ){
      return a.targetMonth-b.targetMonth;
    }
    return a.sort-b.sort||a.title.localeCompare(b.title);
  });
}

