riskyFunctions.saveDetails:
function saveDetails(){
  const post=postById(selectedPostId);
  if(!post)return;
  const item=state.items[post.id];
  const old=clone(item);
  const newStage=document.getElementById("detailStage").value;
  const newDate=document.getElementById("detailDate").value;
  const newLine=document.getElementById("detailLine").value;

  if(old.stage!==newStage)changeStage(post.id,newStage,{silent:true});
  item.date=newDate;
  if(post.source==="holiday"&&old.date!==newDate){
    const dates=Array.isArray(item.holidayStoryDates)?[...item.holidayStoryDates]:[];
    dates[0]=newDate;
    item.holidayStoryDates=dates;
    item.autoHolidayDate=false;
    item.autoHolidayDates=false;
  }
  item.lineId=newLine;
  item.behavior=document.getElementById("detailBehavior").value;
  item.natures=document.getElementById("detailNatures").value.split(",").map(value=>value.trim()).filter(Boolean);
  item.formats=document.getElementById("detailFormats").value.trim();
  item.finalUrl=document.getElementById("detailUrl").value.trim();
  item.notes=document.getElementById("detailNotes").value.trim();
  item.updatedAt=nowIso();

  if(old.date!==item.date)logActivity({type:"date",title:post.title,postId:post.id,value:item.date});
  if(old.lineId!==item.lineId)logActivity({type:"line",title:post.title,postId:post.id,lineName:lineName(item.lineId)});
  if(old.formats!==item.formats)logActivity({type:"formats",title:post.title,postId:post.id});
  if(old.finalUrl!==item.finalUrl)logActivity({type:"file",title:post.title,postId:post.id});
  if(old.notes!==item.notes)logActivity({type:"notes",title:post.title,postId:post.id});

  persist();
  closeDrawer();
  showToast("Alterações salvas.");
}

riskyFunctions.openContent:
function openContent(postId){
  const post=postById(postId);
  if(!post)return;
  openPage("contents");
  currentLineFilter="";
  updateContentLineFilter();
  switchView(state.items[post.id].stage);
  setTimeout(()=>{
    if(state.items[post.id].stage==="ideas"){
      const element=document.querySelector(`.idea-item[data-post="${post.id}"]`);
      if(element){element.scrollIntoView({behavior:"smooth",block:"center"});element.classList.add("open")}
    }else{
      document.querySelector(`[data-details="${post.id}"]`)?.scrollIntoView({behavior:"smooth",block:"center"});
    }
  },80);
}

riskyFunctions.renderOverview:
function renderOverview(){
